const key = $input.item.json.headers?.['x-impar-key'] || '';
const { execSync } = require('child_process');
let envKey = '';
try { envKey = execSync('grep IMPAR_WEBHOOK_KEY ~/.impar-n8n-core/.env | cut -d= -f2-', {timeout:3000}).toString().trim(); } catch(e) {}
if (key !== envKey || !key) return [{ json: { error: 'unauthorized', ai_used: false } }];
return [{ json: { authorized: true, body: $input.item.json.body } }];

const { execSync } = require('child_process');
const prj = process.env.HOME + '/Library/Mobile Documents/com~apple~CloudDocs/Kit-Piloto-Automatico-V30-DISTRIB';
let result = '';
try { result = execSync(`python3 "${prj}/IMPAR_OS/scripts/discover.py" 2>&1`, {timeout:30000}).toString(); } catch(e) { result = e.message; }
return [{ json: { status: 'ok', ai_used: false, timestamp: new Date().toISOString(), output: result.substring(0,500) } }];
